const fs = require("fs");
const path = require("path");

function scanDir(dir) {
  let files = [];
  for (const item of fs.readdirSync(dir)) {
    const full = path.join(dir, item);
    if (fs.statSync(full).isDirectory()) {
      files = files.concat(scanDir(full));
    } else if (full.endsWith(".js")) {
      files.push(full);
    }
  }
  return files;
}

const jsFiles = scanDir(path.resolve("app/js"));
console.log(`Scanning ${jsFiles.length} JavaScript files in app/js/ ...`);

const patterns = [
  { name: ".innerHTML =", regex: /\.innerHTML\s*=/ },
  { name: ".outerHTML =", regex: /\.outerHTML\s*=/ },
  { name: "document.write", regex: /document\.write\s*\(/ },
  { name: "insertAdjacentHTML", regex: /insertAdjacentHTML\s*\(/ },
  { name: "eval()", regex: /\beval\s*\(/ },
  { name: "new Function()", regex: /new\s+Function\s*\(/ },
  { name: "javascript: URI", regex: /javascript\s*:/i }
];

let totalViolations = 0;

for (const pattern of patterns) {
  let matches = [];
  for (const file of jsFiles) {
    const content = fs.readFileSync(file, "utf8");
    const lines = content.split("\n");
    lines.forEach((line, idx) => {
      if (pattern.regex.test(line)) {
        matches.push({ file: path.relative(process.cwd(), file), lineNum: idx + 1, line: line.trim() });
      }
    });
  }

  if (matches.length === 0) {
    console.log(`✔ PASS: Zero occurrences of [${pattern.name}] across app/js/`);
