    console.log(`❌ FAIL: Found ${matches.length} occurrences of [${pattern.name}]:`);
    matches.forEach(m => console.log(`   ${m.file}:${m.lineNum}: ${m.line}`));
    totalViolations += matches.length;
  }
}

